import{_ as t,c as a,o as r,ag as i}from"./chunks/framework.Cycwnjj0.js";const p=JSON.parse('{"title":"Why This Library?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/why.md","filePath":"guide/why.md"}'),o={name:"guide/why.md"};function s(n,e,l,d,h,c){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="why-this-library" tabindex="-1">Why This Library? <a class="header-anchor" href="#why-this-library" aria-label="Permalink to &quot;Why This Library?&quot;">​</a></h1><h2 id="the-problem-with-existing-solutions" tabindex="-1">The Problem with Existing Solutions <a class="header-anchor" href="#the-problem-with-existing-solutions" aria-label="Permalink to &quot;The Problem with Existing Solutions&quot;">​</a></h2><h3 id="native-webgpu-stacks" tabindex="-1">Native WebGPU stacks <a class="header-anchor" href="#native-webgpu-stacks" aria-label="Permalink to &quot;Native WebGPU stacks&quot;">​</a></h3><ul><li>Large platform packages can make server-side installs heavy.</li><li>Local native builds can require extra toolchains.</li><li>API drift makes it harder to share browser-shaped WebGPU code.</li></ul><h3 id="evaluation-criteria" tabindex="-1">Evaluation Criteria <a class="header-anchor" href="#evaluation-criteria" aria-label="Permalink to &quot;Evaluation Criteria&quot;">​</a></h3><ul><li>Documented API coverage</li><li>Clear runtime and platform support</li><li>Browser-style descriptor shapes</li><li>Release readback for published packages</li></ul><h2 id="our-solution" tabindex="-1">Our Solution <a class="header-anchor" href="#our-solution" aria-label="Permalink to &quot;Our Solution&quot;">​</a></h2><h3 id="built-with-rust-wgpu" tabindex="-1">Built with Rust + wgpu <a class="header-anchor" href="#built-with-rust-wgpu" aria-label="Permalink to &quot;Built with Rust + wgpu&quot;">​</a></h3><p><code>@sylphx/webgpu</code> uses Mozilla&#39;s battle-tested <code>wgpu</code> implementation (same as Firefox, Deno, Bevy), providing:</p><ul><li><strong>Small prebuilt packages</strong>: Published platform packages are 1.9-4.6MB</li><li><strong>Consumer install path</strong>: No local Dawn/depot_tools build step expected</li><li><strong>WebGPU-style API</strong>: Browser-style descriptor shapes for portable code</li><li><strong>Modern architecture</strong>: Pure Rust, no C++ complexity</li></ul><h3 id="production-ready" tabindex="-1">Production Ready <a class="header-anchor" href="#production-ready" aria-label="Permalink to &quot;Production Ready&quot;">​</a></h3><p>✅ <strong>Documented API coverage</strong>: Covered package surface is implemented and tested ✅ <strong>Cross-platform</strong>: macOS, Linux, Windows (x64 + ARM64) ✅ <strong>Runtime support</strong>: Node.js 18+ and Bun 1.0+ ✅ <strong>Well tested</strong>: Local suite covering the documented package surface with real GPU operations ✅ <strong>Minimal dependencies</strong>: Just native bindings, no bloat</p><h2 id="role-in-the-sylphxai-python-class-typescript-stack" tabindex="-1">Role in the SylphxAI Python-Class TypeScript Stack <a class="header-anchor" href="#role-in-the-sylphxai-python-class-typescript-stack" aria-label="Permalink to &quot;Role in the SylphxAI Python-Class TypeScript Stack&quot;">​</a></h2><p><code>@sylphx/webgpu</code> is the GPU substrate, not the NumPy or PyTorch API layer. That boundary is intentional:</p><ul><li>this package owns WebGPU adapter/device behavior, command submission, buffer and texture primitives, native platform artifacts, examples, and release readback;</li><li>numerical libraries own Python-compatible syntax, tensor/array semantics, autograd semantics, benchmark admission, and release claims;</li><li>benchmark reports may cite this backend only when they record package version, platform package, adapter/backend info, and workload shape.</li></ul><p>This keeps the WebGPU package reusable across rendering, compute, scientific workloads, and ML backends without hardcoding one consumer&#39;s benchmark story. For the durable boundary decision, see <a href="/adr/001-python-performance-backend-contract.html">Python Performance Backend Contract</a>.</p><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h3><p><strong>Binary Sizes (Actual Prebuilt Binaries):</strong></p><ul><li>macOS ARM64: 1.9MB</li><li>macOS x64: 2.2MB</li><li>Linux ARM64: 3.0MB</li><li>Linux x64: 3.5MB</li><li>Windows ARM64: 4.1MB</li><li>Windows x64: 4.6MB</li></ul><p><strong>Build Time (Measured Clean Build):</strong></p><ul><li>This library: 29 seconds (Cargo release build)</li><li>@kmamal/gpu: 1-3 hours (Dawn + depot_tools)</li></ul><h2 id="design-philosophy" tabindex="-1">Design Philosophy <a class="header-anchor" href="#design-philosophy" aria-label="Permalink to &quot;Design Philosophy&quot;">​</a></h2><h3 id="lightweight" tabindex="-1">Lightweight <a class="header-anchor" href="#lightweight" aria-label="Permalink to &quot;Lightweight&quot;">​</a></h3><p>No unnecessary abstractions. Thin binding layer that exposes WebGPU API directly.</p><h3 id="fast" tabindex="-1">Fast <a class="header-anchor" href="#fast" aria-label="Permalink to &quot;Fast&quot;">​</a></h3><p>Built with Rust and napi-rs on top of wgpu. Runtime performance claims should be tied to measured workloads that record package version, platform package, adapter/backend info, and synchronization/readback boundaries.</p><h3 id="reliable" tabindex="-1">Reliable <a class="header-anchor" href="#reliable" aria-label="Permalink to &quot;Reliable&quot;">​</a></h3><p>Comprehensive error handling. Validation at API boundaries. Clear error messages.</p><h3 id="modern" tabindex="-1">Modern <a class="header-anchor" href="#modern" aria-label="Permalink to &quot;Modern&quot;">​</a></h3><p>ES modules, TypeScript definitions, async/await. Built for modern JavaScript.</p><h2 id="when-to-use-this" tabindex="-1">When to Use This <a class="header-anchor" href="#when-to-use-this" aria-label="Permalink to &quot;When to Use This&quot;">​</a></h2><p>✅ <strong>Machine learning inference</strong> on GPU ✅ <strong>Backend kernels</strong> for TypeScript numerical libraries ✅ <strong>Image/video processing</strong> pipelines ✅ <strong>Scientific computing</strong> in Node.js ✅ <strong>Data visualization</strong> rendering ✅ <strong>Cryptography</strong> and parallel algorithms</p><h2 id="when-not-to-use-this" tabindex="-1">When NOT to Use This <a class="header-anchor" href="#when-not-to-use-this" aria-label="Permalink to &quot;When NOT to Use This&quot;">​</a></h2><p>❌ <strong>Web browsers</strong> - Use native WebGPU API ❌ <strong>Training large models</strong> - Use PyTorch/TensorFlow ❌ <strong>Game development</strong> - Use game engines</p><h2 id="comparison-table" tabindex="-1">Comparison Table <a class="header-anchor" href="#comparison-table" aria-label="Permalink to &quot;Comparison Table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>@kmamal/gpu (Dawn)</th><th>This Library</th></tr></thead><tbody><tr><td><strong>WebGPU API</strong></td><td>⚠️ Custom API</td><td>✅ Standards-aligned browser API</td></tr><tr><td><strong>Binary Size</strong></td><td>50-150MB</td><td>1.9-4.6MB</td></tr><tr><td><strong>Build Time</strong></td><td>1-3 hours</td><td>~30 seconds</td></tr><tr><td><strong>API Coverage</strong></td><td>Partial</td><td>Documented package surface</td></tr><tr><td><strong>Browser Compatible</strong></td><td>❌ Node.js only</td><td>✅ Shares code</td></tr><tr><td><strong>TypeScript</strong></td><td>❌</td><td>✅ Full definitions</td></tr><tr><td><strong>Bun Support</strong></td><td>⚠️ Limited</td><td>✅ Native support</td></tr><tr><td><strong>Status</strong></td><td>0.x Pre-release</td><td>v1.0 Production</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>Ready to try it? Head to <a href="/guide/getting-started.html">Getting Started</a> →</p>',38)])])}const g=t(o,[["render",s]]);export{p as __pageData,g as default};
